module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic done
);

    typedef enum logic [1:0] {
        S_IDLE      = 2'b00,
        S_DATA      = 2'b01,
        S_STOP      = 2'b10,
        S_WAIT_STOP = 2'b11
    } state_t;

    state_t state, next_state;
    logic [2:0] bit_cnt;

    // Sequential logic
    always_ff @(posedge clk) begin
        if (reset) begin
            state   <= S_IDLE;
            bit_cnt <= 3'd0;
            done    <= 1'b0;
        end else begin
            state   <= next_state;
            done    <= (state == S_STOP && in == 1'b1);

            if (state == S_IDLE && in == 1'b0) begin
                bit_cnt <= 3'd0;
            end else if (state == S_DATA) begin
                bit_cnt <= bit_cnt + 3'd1;
            end
        end
    end

    // Combinational next state logic
    always_comb begin
        next_state = state;

        case (state)
            S_IDLE: begin
                if (in == 1'b0) begin
                    next_state = S_DATA;
                end
            end

            S_DATA: begin
                if (bit_cnt == 3'd7) begin
                    next_state = S_STOP;
                end
            end

            S_STOP: begin
                if (in == 1'b1) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT_STOP;
                end
            end

            S_WAIT_STOP: begin
                if (in == 1'b1) begin
                    next_state = S_IDLE;
                end
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

