module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic done;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .done(done)
    );

    // Clock generation: 10 time units period
    initial clk = 0;
    always #5 clk = ~clk;

    task send_bit(input bit b);
        begin
            in = b;
            @(posedge clk);
        end
    endtask

    // Task to send a full byte frame
    task send_frame(input [7:0] data, input bit correct_stop);
        integer i;
        begin
            // Start bit (0)
            send_bit(1'b0);
            // 8 data bits, LSB first
            for (i = 0; i < 8; i++) begin
                send_bit(data[i]);
            end
            // Stop bit
            if (correct_stop)
                send_bit(1'b1);
            else
                send_bit(1'b0); // incorrect stop bit
        end
    endtask

    initial begin
        reset = 1;
        in = 1; // idle
        @(posedge clk);
        @(posedge clk);
        reset = 0;
        @(posedge clk);

        // Test 1: Send a correct byte (e.g. 8'hA5)
        $display("Sending correct byte 0xA5...");
        send_frame(8'hA5, 1'b1);

        // Wait a cycle or two and check done pulse
        // Note: done pulses on the clock edge where stop bit is sampled.
        @(posedge clk);
        if (done !== 1'b1) begin
            $display("SELFTEST FAIL: Expected done to be 1 after correct byte, got %b", done);
            $finish;
        end
        @(posedge clk);
        if (done !== 1'b0) begin
            $display("SELFTEST FAIL: Expected done to drop to 0, got %b", done);
            $finish;
        end

        // Test 2: Send two back-to-back correct bytes (0x33, then 0xCC)
        $display("Sending back-to-back bytes...");
        send_frame(8'h33, 1'b1);
        // check done for first byte
        @(posedge clk);
        if (done !== 1'b1) begin
            $display("SELFTEST FAIL: Expected done for first back-to-back byte");
            $finish;
        end

        send_frame(8'hCC, 1'b1);
        @(posedge clk);
        if (done !== 1'b1) begin
            $display("SELFTEST FAIL: Expected done for second back-to-back byte");
            $finish;
        end
        @(posedge clk);

        // Test 3: Incorrect stop bit (stop bit = 0), then wait until stop bit found (in = 1), then send valid byte
        $display("Sending frame with incorrect stop bit...");
        send_frame(8'h55, 1'b0); // stop bit is 0
        @(posedge clk);
        if (done === 1'b1) begin
            $display("SELFTEST FAIL: done should not be high on incorrect stop bit");
            $finish;
        end

        // FSM should now be waiting for stop bit (in == 1). Let's keep in = 0 for a couple cycles.
        in = 1'b0;
        @(posedge clk);
        @(posedge clk);
        if (done === 1'b1) begin
            $display("SELFTEST FAIL: done should still be 0 while waiting for stop bit");
            $finish;
        end

        // Now provide the stop bit (in = 1)
        in = 1'b1;
        @(posedge clk);
        // Now it should be back in IDLE and ready for next byte.
        // Let's send a valid frame now (0xAA)
        send_frame(8'hAA, 1'b1);
        @(posedge clk);
        if (done !== 1'b1) begin
            $display("SELFTEST FAIL: Expected done after recovery from incorrect stop bit");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

